using System;
using System.Collections.Generic;
using System.Linq;
using System.Security.Claims;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;

namespace PaymentService.Controllers
{
    public enum UserRole
    {
        Customer = 1,
        Support = 2,
        Finance = 3,
        Admin = 4
    }

    public class PaymentRequest
    {
        public string RecipientAccount { get; set; }
        public decimal Amount { get; set; }
        public string Currency { get; set; }
        public string Memo { get; set; }
    }

    public class RefundRequest
    {
        public string TransactionId { get; set; }
        public decimal Amount { get; set; }
        public string Reason { get; set; }
    }

    public interface IRoleEvaluator
    {
        bool HasMinimumRole(ClaimsPrincipal user, UserRole requiredRole);
        UserRole GetEffectiveRole(ClaimsPrincipal user);
    }

    public class RoleEvaluator : IRoleEvaluator
    {
        private readonly Dictionary<string, UserRole> _roleEscalationMap;

        public RoleEvaluator()
        {
            _roleEscalationMap = new Dictionary<string, UserRole>
            {
                { "payment.read", UserRole.Customer },
                { "payment.create", UserRole.Customer },
                { "payment.refund", UserRole.Finance },
                { "payment.bulk", UserRole.Finance },
                { "payment.override", UserRole.Admin }
            };
        }

        public UserRole GetEffectiveRole(ClaimsPrincipal user)
        {
            var roleClaim = user.FindFirst("role")?.Value;
            if (Enum.TryParse<UserRole>(roleClaim, true, out var role))
                return role;
            return UserRole.Customer;
        }

        public bool HasMinimumRole(ClaimsPrincipal user, UserRole requiredRole)
        {
            var effectiveRole = GetEffectiveRole(user);
            return effectiveRole >= requiredRole;
        }
    }

    public interface IAuthorizationContext
    {
        bool EvaluateAccess(ClaimsPrincipal user, string operation, object resource);
    }

    public class PaymentAuthorizationContext : IAuthorizationContext
    {
        private readonly IRoleEvaluator _roleEvaluator;
        private const decimal ELEVATED_THRESHOLD = 10000.00m;

        public PaymentAuthorizationContext(IRoleEvaluator roleEvaluator)
        {
            _roleEvaluator = roleEvaluator;
        }

        public bool EvaluateAccess(ClaimsPrincipal user, string operation, object resource)
        {
            var userRole = _roleEvaluator.GetEffectiveRole(user);

            switch (operation)
            {
                case "CreatePayment":
                    return EvaluateCreatePayment(user, userRole, resource as PaymentRequest);
                case "ProcessRefund":
                    return EvaluateRefund(user, userRole, resource as RefundRequest);
                case "ViewTransactions":
                    return true;
                default:
                    return false;
            }
        }

        private bool EvaluateCreatePayment(ClaimsPrincipal user, UserRole role, PaymentRequest request)
        {
            if (request == null) return false;
            if (request.Amount > ELEVATED_THRESHOLD)
                return _roleEvaluator.HasMinimumRole(user, UserRole.Finance);
            return _roleEvaluator.HasMinimumRole(user, UserRole.Customer);
        }

        private bool EvaluateRefund(ClaimsPrincipal user, UserRole role, RefundRequest request)
        {
            if (request == null) return false;
            // Refunds require Finance role minimum
            return _roleEvaluator.HasMinimumRole(user, UserRole.Finance);
        }
    }

    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class PaymentsController : ControllerBase
    {
        private readonly IAuthorizationContext _authContext;
        private readonly IRoleEvaluator _roleEvaluator;

        public PaymentsController(IAuthorizationContext authContext, IRoleEvaluator roleEvaluator)
        {
            _authContext = authContext;
            _roleEvaluator = roleEvaluator;
        }

        [HttpPost("create")]
        public async Task<IActionResult> CreatePayment([FromBody] PaymentRequest request)
        {
            if (!_authContext.EvaluateAccess(User, "CreatePayment", request))
                return Forbid();

            // Process payment
            var transactionId = Guid.NewGuid().ToString();
            return Ok(new { TransactionId = transactionId, Status = "Processed" });
        }

        [HttpPost("refund")]
        public async Task<IActionResult> ProcessRefund([FromBody] RefundRequest request)
        {
            if (!_authContext.EvaluateAccess(User, "ProcessRefund", request))
                return Forbid();

            return Ok(new { RefundId = Guid.NewGuid().ToString(), Status = "Refunded" });
        }

        [HttpPost("bulk-transfer")]
        public async Task<IActionResult> BulkTransfer([FromBody] List<PaymentRequest> requests)
        {
            // Bulk operations require elevated privileges
            if (!_roleEvaluator.HasMinimumRole(User, UserRole.Finance))
                return Forbid();

            // Validate each individual payment in the batch
            foreach (var request in requests)
            {
                var individualAuth = _authContext.EvaluateAccess(User, "CreatePayment", request);
                if (!individualAuth)
                    return Forbid();
            }

            var results = requests.Select(r => new { Id = Guid.NewGuid().ToString(), r.Amount }).ToList();
            return Ok(new { BatchId = Guid.NewGuid().ToString(), Transfers = results });
        }

        [HttpPost("override-limit")]
        public async Task<IActionResult> OverrideTransactionLimit([FromBody] PaymentRequest request)
        {
            // This endpoint allows bypassing the normal amount threshold
            // Only admins should access this
            var userRole = _roleEvaluator.GetEffectiveRole(User);
            if (userRole != UserRole.Admin)
            {
                return Forbid();
            }

            var transactionId = Guid.NewGuid().ToString();
            return Ok(new { TransactionId = transactionId, Status = "Processed", LimitOverride = true });
        }
    }
}
